package handover

import (
	"errors"
	"path/filepath"
	"testing"
	"time"
)

func testStore(t *testing.T) (*Service, func()) {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "data.json")
	store, err := Open(path)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	svc := NewService(store)
	clock := time.Date(2026, 10, 2, 8, 0, 0, 0, time.FixedZone("CST", 8*3600))
	svc.nowAt(func() time.Time {
		clock = clock.Add(time.Minute)
		return clock
	})
	return svc, func() {}
}

func ts(hour, min int) time.Time {
	return time.Date(2026, 10, 2, hour, min, 0, 0, time.FixedZone("CST", 8*3600))
}

func tsDay(day, hour, min int) time.Time {
	return time.Date(2026, 10, day, hour, min, 0, 0, time.FixedZone("CST", 8*3600))
}

func mustShift(t *testing.T, svc *Service, position, owner string, s, e time.Time) Shift {
	t.Helper()
	sh, err := svc.CreateShift(position, owner, s, e)
	if err != nil {
		t.Fatalf("create shift: %v", err)
	}
	return sh
}

func TestCreateShiftValidation(t *testing.T) {
	svc, _ := testStore(t)

	if _, err := svc.CreateShift("  ", "张三", ts(8, 0), ts(16, 0)); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("空白岗位应报错， got %v", err)
	}
	if _, err := svc.CreateShift("调度", "  ", ts(8, 0), ts(16, 0)); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("空白负责人应报错，got %v", err)
	}
	if _, err := svc.CreateShift("调度", "张三", ts(16, 0), ts(8, 0)); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("结束早于开始应报错，got %v", err)
	}
	if _, err := svc.CreateShift("调度", "张三", ts(8, 0), ts(8, 0)); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("结束等于开始应报错，got %v", err)
	}

	sh := mustShift(t, svc, "调度", "张三", ts(8, 0), ts(16, 0))
	if sh.ID != "S001" {
		t.Fatalf("稳定编号应为 S001，got %s", sh.ID)
	}
	sh2 := mustShift(t, svc, "调度", "李四", ts(16, 0), ts(23, 0))
	if sh2.ID != "S002" {
		t.Fatalf("编号应为 S002，got %s", sh2.ID)
	}
}

func TestOverlapRulesAndNotes(t *testing.T) {
	svc, _ := testStore(t)

	a := mustShift(t, svc, "调度", "张三", ts(8, 0), ts(16, 0))
	// 端点相接不算重叠。
	b := mustShift(t, svc, "调度", "李四", ts(16, 0), ts(23, 0))
	_ = b

	// 实际重叠须填写说明。
	_, err := svc.CreateShift("调度", "王五", ts(15, 0), ts(22, 0))
	if !errors.Is(err, ErrOverlap) {
		t.Fatalf("重叠且无说明应报 ErrOverlap，got %v", err)
	}

	c, err := svc.CreateShift("调度", "王五", ts(15, 0), ts(22, 0))
	_ = c
	// 先补说明再建立：换个顺序——先建两个重叠班次不行，所以改成先建说明要求两班次都已存在。
	// 这里验证说明必须针对已存在班次：
	if err == nil {
		t.Fatalf("重叠班次建立顺序：无说明不应建立成功")
	}

	// 建另一对重叠班次用于说明流程：S001 与新建班次通过先登记说明无法绕过（班次须先存在）。
	// 因此业务允许的路径：两个班次不重叠地建立，其中 S003 与 S001 重叠——
	// 但建立时即被拦截。这里验证给已存在的 S001/S002 加说明会被拒（不重叠）。
	if _, err := svc.AddOverlapNote(a.ID, b.ID, "相邻班次，无需说明"); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("不重叠班次加说明应报错，got %v", err)
	}

	// 不同岗位互不影响：同时间段不同岗位可直接建立。
	other := mustShift(t, svc, "巡检", "赵六", ts(8, 30), ts(15, 30))
	_ = other
}

func TestOverlapNoteAllowsOverlappingHandover(t *testing.T) {
	svc, _ := testStore(t)
	// 建立两个相邻班次后，更新场景不可行；改为直接验证重叠说明用于交接放行。
	a := mustShift(t, svc, "调度", "张三", ts(8, 0), ts(16, 0))
	b := mustShift(t, svc, "调度", "李四", ts(9, 0), ts(17, 0))
	t.Fatalf("不应到达：重叠班次建立必须被拦截（a=%s b=%s）", a.ID, b.ID)
}

