		t.Fatalf("close b: %v", err)
	}
	c := mustShift(t, f, "调度", "赵六", tsDay(2, 23, 0), tsDay(3, 7, 0), "")

	// 接收项未在 b 关闭，随 b 再次交接，保留原编号和历史。
	h2, err := f.svc.CreateHandover(b.ID, c.ID)
	if err != nil {
		t.Fatalf("chain handover: %v", err)
	}
